import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.yZB1U4Nl.js";const u=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"cli.md","filePath":"cli.md"}'),i={name:"cli.md"};function n(d,e,l,r,c,p){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>The <code>vlo</code> command ships with <code>@oona/vlo</code> (<code>npx vlo …</code>). Four verbs, one profile: whatever runs on your laptop, what <code>doctor</code> checks and what <code>deploy</code> renders all come from the same entry in <code>vlo.config.ts</code>. See <a href="./configuration">configuration.md</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vlo dev    [--config &lt;path&gt;] [--profile &lt;name&gt;] [--port &lt;n&gt;]</span></span>
<span class="line"><span>vlo serve  --profile &lt;name&gt;  [--config &lt;path&gt;] [--port &lt;n&gt;]</span></span>
<span class="line"><span>vlo doctor --profile &lt;name&gt;  [--config &lt;path&gt;] [--json] [--no-migrate]</span></span>
<span class="line"><span>vlo deploy --profile &lt;name&gt;  [--config &lt;path&gt;] [--out deploy/vlo] [--apply]</span></span>
<span class="line"><span>vlo --help | -h</span></span>
<span class="line"><span>vlo --version</span></span></code></pre></div><p>Shared flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--config &lt;path&gt;</code></td><td>Config file to load instead of auto-detecting <code>vlo.config.{ts,js,mjs}</code>.</td></tr><tr><td><code>--profile &lt;name&gt;</code></td><td>Profile inside the config. Every verb falls back to <code>VLO_PROFILE</code>; <code>serve</code>, <code>doctor</code> and <code>deploy</code> fail without one, <code>dev</code> picks <code>local</code> or the only profile.</td></tr><tr><td><code>--help</code>, <code>-h</code></td><td>Print usage to stdout and exit 0.</td></tr><tr><td><code>--version</code></td><td>Print the SDK version to stdout and exit 0.</td></tr></tbody></table><p><code>--help</code> and <code>--version</code> are being added alongside this documentation; earlier builds print usage to stderr and exit 1 for any unknown verb.</p><h2 id="vlo-dev" tabindex="-1"><code>vlo dev</code> <a class="header-anchor" href="#vlo-dev" aria-label="Permalink to &quot;\`vlo dev\`&quot;">​</a></h2><p>The whole engine on a laptop: SQLite journal, file blob store, every role in one process.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ npx vlo dev</span></span>
<span class="line"><span>  ✓ journal  sqlite:///home/me/app/.vlo/dev.db</span></span>
<span class="line"><span>  ✓ found 2 workflows   example · hello</span></span>
<span class="line"><span>  ✓ found 1 worker   in-process</span></span>
<span class="line"><span>  ✓ api      http://localhost:4100</span></span></code></pre></div><ul><li>Profile: <code>--profile</code>, else <code>VLO_PROFILE</code>, else <code>local</code>, else the only profile in the file; with no config file the built-in <code>local</code> profile is used.</li><li>Relative <code>sqlite://</code> and <code>file://</code> paths resolve against the config file&#39;s directory, and the journal and blob store create their own directories.</li><li>Migrates the journal, imports every module the globs match, binds the port, starts the dispatcher in the profile&#39;s mode (<code>loop</code> unless configured otherwise).</li><li>No hot reload: restart after editing a workflow.</li><li>The third line is one of <code>found N workers in-process</code>, <code>workers remote via queues …</code>, or a stderr warning <code>⚠ no workers found</code> when there are neither.</li><li>Dispatcher warnings (a push refused, a task with no transport) go to stderr as <code>⚠ …</code>.</li><li><code>SIGINT</code> / <code>SIGTERM</code> stop the dispatcher, wait up to 5 s for in-process handlers, then close the journal.</li></ul><h2 id="vlo-serve" tabindex="-1"><code>vlo serve</code> <a class="header-anchor" href="#vlo-serve" aria-label="Permalink to &quot;\`vlo serve\`&quot;">​</a></h2><p>The production twin of <code>dev</code>: identical code path, no conveniences.</p><ul><li><code>--profile</code> (or <code>VLO_PROFILE</code>) is required. There is no SQLite fallback.</li><li>Nothing is created on disk.</li><li>Port: <code>--port</code>, then <code>PORT</code>, then the profile&#39;s <code>port</code>, then <code>4100</code>.</li><li>Prints the same ✓ lines as <code>dev</code>; <code>/healthz</code> answers <code>{ ok, roles, workflows }</code>.</li></ul><p><code>vlo serve --profile prod</code> is what the generated Cloud Run image runs.</p><h2 id="vlo-doctor" tabindex="-1"><code>vlo doctor</code> <a class="header-anchor" href="#vlo-doctor" aria-label="Permalink to &quot;\`vlo doctor\`&quot;">​</a></h2><p>Is this profile actually wired up? Every check is a real round trip, so it fails here rather than three minutes into a deploy. Cheap enough to run on every boot of a new environment.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vlo doctor --profile prod</span></span>
<span class="line"><span>  ✓ journal    postgres · commit round trip 4 ms</span></span>
<span class="line"><span>  ✓ migrate    schema up to date</span></span>
<span class="line"><span>  ✓ blob       gcs://my-bucket/vlo · 1 KiB round trip</span></span>
<span class="line"><span>  ✓ kernel     protocol 1 · 288 KiB</span></span>
<span class="line"><span>  ⚠ schemas    2/4 registered · missing example.plan · example.approve</span></span>
<span class="line"><span>               → these register on the next host boot</span></span>
<span class="line"><span>  ✓ queue:llm  push · https://workers.example.com/healthz reachable</span></span>
<span class="line"><span>  ✓ queue:media  pull · served by pollers</span></span>
<span class="line"><span>  ✓ roles      orchestrator · api · dispatcher loop</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Check</th><th>What it does</th><th>⚠ / ✗ when</th></tr></thead><tbody><tr><td><code>journal</code></td><td>Opens the URL and runs one empty write transaction (lock + commit).</td><td>✗ unreachable, bad credentials, missing database, unsupported scheme.</td></tr><tr><td><code>migrate</code></td><td>Applies pending migrations.</td><td>✗ migration failed; ⚠ skipped with <code>--no-migrate</code>.</td></tr><tr><td><code>blob</code></td><td>Writes a 1 KiB probe and reads it back. Content-addressed, so re-runs write nothing.</td><td>✗ cannot write, digest mismatch, truncated read.</td></tr><tr><td><code>kernel</code></td><td>Finds the wasm, loads it, compares protocol versions.</td><td>✗ not found or protocol mismatch; ⚠ over the 1 MiB budget.</td></tr><tr><td><code>schemas</code></td><td>Looks up every registered activity and signal hash in the <code>schemas</code> table.</td><td>⚠ some not registered yet (a host boot registers them).</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>One per queue. Push: <code>GET &lt;url&gt;/healthz</code> with a 3 s timeout. Pull: always ok. No URL: needs an in-process worker.</td><td>✗ unreachable, unhealthy, no URL and no worker, URL not absolute; ⚠ push URL with no <code>secret</code>.</td></tr><tr><td><code>roles</code></td><td>Roles versus dispatcher mode.</td><td>⚠ orchestrator in <code>manual</code> mode with no <code>deploy.cron</code>: nothing would ever tick.</td></tr></tbody></table><p>Flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--json</code></td><td>Print the checks as a JSON array instead of the table.</td></tr><tr><td><code>--no-migrate</code></td><td>Never write to the journal. A missing schema then shows up as a failed commit.</td></tr></tbody></table><p><code>--json</code> shape, one object per check:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;journal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sqlite · commit round trip 1 ms&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;schemas&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1/2 registered · missing demo.echo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;these register on the next host boot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>status</code> is <code>&quot;ok&quot;</code>, <code>&quot;warn&quot;</code> or <code>&quot;fail&quot;</code>; <code>hint</code> is present on anything that is not ok. Any <code>fail</code> sets exit code 1, so a pipeline can gate on it.</p><h2 id="vlo-deploy" tabindex="-1"><code>vlo deploy</code> <a class="header-anchor" href="#vlo-deploy" aria-label="Permalink to &quot;\`vlo deploy\`&quot;">​</a></h2><p>Renders the platform files for a profile and stops there. Generation is not application: nothing touches a cloud account without a human running the printed commands.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vlo deploy --profile prod</span></span>
<span class="line"><span>  ✓ deploy/vlo/cloud-run/Dockerfile</span></span>
<span class="line"><span>  ✓ deploy/vlo/cloud-run/cloudbuild.yaml</span></span>
<span class="line"><span>  ✓ deploy/vlo/cloud-run/cloud-run-vlo.tf</span></span>
<span class="line"><span>  ✓ deploy/vlo/cloud-run/cloudbuild-vlo.tf</span></span>
<span class="line"><span>  ✓ deploy/vlo/cloud-run/README.md</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--out &lt;dir&gt;</code></td><td>Output directory, relative to the working directory. Default <code>deploy/vlo</code>.</td></tr><tr><td><code>--apply</code></td><td>After writing, print the exact <code>gcloud</code> / <code>terraform</code> / <code>vercel</code> commands to run. Nothing is executed.</td></tr></tbody></table><p>Requires <code>deploy: { target: &quot;cloud-run&quot; | &quot;vercel&quot;, … }</code> on the profile; the error names the profile otherwise. Resolved secrets (the journal URL, tokens) never reach a generated file; templates read them from environment variables or Secret Manager at run time. The file-by-file contents are described in <a href="./deployment">deployment.md</a>.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>0</code></td><td>The verb finished; <code>doctor</code> found no ✗.</td></tr><tr><td><code>1</code></td><td>Unknown verb (usage on stderr); any thrown error (message on stderr), including a missing <code>--profile</code>, an unknown profile, an unset <code>env()</code> variable; <code>doctor</code> with at least one ✗.</td></tr></tbody></table><h2 id="running-from-source" tabindex="-1">Running from source <a class="header-anchor" href="#running-from-source" aria-label="Permalink to &quot;Running from source&quot;">​</a></h2><p>From a checkout of the repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @oona/vlo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../../examples/hello/vlo.config.ts</span></span></code></pre></div><p>The kernel wasm is committed at <code>sdk/ts/sdk/wasm/vlo_kernel_bg.wasm</code>; rebuild it after kernel changes with <code>./scripts/build-kernel.sh</code> (needs <code>wasm-pack</code> and the pinned Rust toolchain), or point <code>VLO_KERNEL_WASM</code> at a freshly built file. <code>pnpm --filter @oona/vlo test</code> runs the SDK suite on SQLite; set <code>VLO_TEST_DATABASE_URL</code> to also run it on Postgres.</p><p>Every verb is also a library call: <code>dev()</code>, <code>serveCommand()</code>, <code>doctor()</code> / <code>runChecks()</code> and <code>deploy()</code> under <code>sdk/ts/sdk/src/cli/</code> take an options object and return what they started, checked or wrote.</p>`,35)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
